update artists set instagram='shasha.lively' where slug='shasha' and instagram='new';
update artists set instagram=coalesce(nullif(instagram,''),'heyydidar') where slug='didar';
update artists set instagram=coalesce(nullif(instagram,''),'yngdaku') where slug='daku';
update artists set instagram=coalesce(nullif(instagram,''),'kikiwaap'), based_city=coalesce(based_city,'Berlin') where slug='kairavi';
update artists set instagram=coalesce(nullif(instagram,''),'baby_nabi_nabi') where slug='bb-nabi';
update artists set instagram=coalesce(nullif(instagram,''),'nacncheeze') where slug='nac-n-cheeze';
update artists set instagram=coalesce(nullif(instagram,''),'prog.rescue'), based_city=coalesce(based_city,'Mumbai') where slug='prog-rescue';
update artists set instagram=coalesce(nullif(instagram,''),'citizen.kale') where slug='citizen-kale';
update artists set based_city=coalesce(based_city,'Goa'), links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/RattyAtty/') where slug='rattyatty' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set based_city=coalesce(based_city,'Chennai') where slug='ezzyland';
update artists set based_city=coalesce(based_city,'Delhi') where slug in ('sage','sourog','ashna','no-mo-soul');
update artists set based_city=coalesce(based_city,'Bombay') where slug='anisha';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/brnsctr/') where slug='brnsctr' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/drumattic/') where slug='drum-attic' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/madstarbase/') where slug='madstarbase' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/subzdelhi/') where slug='sub-z' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/avantikabakshi/') where slug='avantika' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/malfnktion/') where slug='malfnktion' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set links=coalesce(links,'{}'::jsonb)||jsonb_build_object('mixcloud','https://www.mixcloud.com/sachit_sethi/') where slug='no-mo-soul' and not coalesce(links,'{}'::jsonb) ? 'mixcloud';
update artists set verify_note=replace(verify_note,'Needs Param: identity probable, not proven (see run 2026-11-10-ndcr notes). ','Identity confirmed: Kiosk Radio and Naviluna set descriptions call Rafiki the alter ego of Sohail Arora, Krunk founder, Mumbai. ') where slug='rafiki';
